mapper.select:

SELECT id, user_id, score, action_type, description, record_date, created_at
FROM green_score_records
WHERE user_id = #{userId}
AND record_date BETWEEN #{startDate} AND #{endDate}
ORDER BY record_date DESC, created_at DESC

SELECT COALESCE(SUM(score), 0) AS total_score
FROM green_score_records
WHERE user_id = #{userId}

SELECT id, nickname, avatar, total_score, `rank`
FROM user_score_ranking
WHERE id = #{userId}
